import { useEffect, useState } from "react";
import { API } from "../api/api";
import Navbar from "../components/Navbar"; // ✅ ADD THIS

export default function CreateSurvey() {
  const [questions, setQuestions] = useState([]);
  const [selected, setSelected] = useState([]);
  const [visibleCount, setVisibleCount] = useState(4);

  useEffect(() => {
    API.get("/questions").then((res) => setQuestions(res.data));
  }, []);

  const toggleSelect = (id) => {
    setSelected((prev) =>
      prev.includes(id)
        ? prev.filter((q) => q !== id)
        : [...prev, id]
    );
  };

  const createSurvey = async () => {
    try {
      await API.post("/surveys", { questions: selected });
      alert("Survey Created 🚀");
      
      setSelected([]);
    } catch (err) {
      alert("Error creating survey");
    }
  };

  const loadMore = () => {
    setVisibleCount((prev) => prev + 4);
  };

  return (
    <>
      {/* ✅ NAVBAR ADDED */}
      <Navbar />

      <style>{`
        *{
          margin:0;
          padding:0;
          box-sizing:border-box;
          font-family:Arial, sans-serif;
        }

        .survey-page{
          min-height:100vh;
          padding:40px 20px;
          background:linear-gradient(135deg,#0f172a,#1e293b,#0b1220);
          color:white;
        }

        .title{
          text-align:center;
          font-size:32px;
          margin-bottom:30px;
        }

        .question-list{
          display:flex;
          flex-direction:column;
          gap:12px;
          align-items:center;
        }

        .card{
          width:55%;
          padding:12px 18px;
          border-radius:12px;
          background:rgba(255,255,255,0.08);
          display:flex;
          justify-content:space-between;
          align-items:center;
          cursor:pointer;
          transition:0.3s;
        }

        .card:hover{
          transform:scale(1.02);
        }

        .selected{
          border:1px solid #22c55e;
          background:rgba(34,197,94,0.15);
        }

        .checkbox{
          width:18px;
          height:18px;
          accent-color:#22c55e;
        }

        .plus-btn{
          width:45px;
          height:45px;
          border:none;
          border-radius:50%;
          background:#22c55e;
          color:white;
          font-size:28px;
          cursor:pointer;
          margin-top:20px;
        }

        .create-btn{
          margin-top:25px;
          padding:12px 28px;
          border:none;
          border-radius:10px;
          background:#3b82f6;
          color:white;
          cursor:pointer;
          font-size:16px;
        }

        .center{
          text-align:center;
        }

        @media(max-width:768px){
          .card{
            width:90%;
          }
        }
      `}</style>

      <div className="survey-page">
        <h2 className="title">Create Survey 🧠</h2>

        <div className="question-list">
          {questions.slice(0, visibleCount).map((q) => {
            const isSelected = selected.includes(q._id);

            return (
              <div
                key={q._id}
                className={`card ${isSelected ? "selected" : ""}`}
                onClick={() => toggleSelect(q._id)}
              >
                <span>{q.text}</span>

                <input
                  type="checkbox"
                  checked={isSelected}
                  onChange={() => toggleSelect(q._id)}
                  className="checkbox"
                />
              </div>
            );
          })}
        </div>

        {/* PLUS BUTTON */}
        {visibleCount < questions.length && (
          <div className="center">
            <button className="plus-btn" onClick={loadMore}>
              +
            </button>
          </div>
        )}

        {/* CREATE BUTTON */}
        <div className="center">
          <button className="create-btn" onClick={createSurvey}>
            Create Survey 🚀
          </button>
        </div>
      </div>
    </>
  );
}
